/**
 * Filter types matching the platform filter contract.
 *
 * Discriminated on `type` with values matching platform filter type names.
 */
export type ValueType = "BOOLEAN" | "CURRENT_USER" | "DATE" | "DATETIME" | "FIELD" | "NULL" | "NUMBER" | "RECORD_FIELD" | "REFERENCE" | "TEXT" | "UUID";
export type FilterReference = {
    type: "TRIGGER";
    name: string;
} | {
    type: "TASK";
    taskId: string;
    name: string;
} | {
    type: "TASK";
    taskRefKey: string;
    name: string;
} | {
    type: "FOR_EACH";
    forEachTaskId: string;
    name: string;
} | {
    type: "FOR_EACH";
    forEachTaskRefKey: string;
    name: string;
} | {
    type: "VALUE";
    value: unknown;
} | {
    type: "VARIABLE";
    name: string;
    variableId?: string;
};
export type FilterValue<FieldValue = string, ReferenceValue = FilterReference> = {
    type: "TEXT";
    value: string;
} | {
    type: "NUMBER";
    value: number;
} | {
    type: "BOOLEAN";
    value: boolean;
} | {
    type: "UUID";
    value: string;
} | {
    type: "DATE";
    value: string;
} | {
    type: "DATETIME";
    value: string;
} | {
    type: "FIELD";
    value: FieldValue;
    aspect?: string;
    treatNullAsEquals?: boolean;
} | {
    type: "NULL";
} | {
    type: "CURRENT_USER";
    valueType?: "ID" | "EMAIL" | "DOMAIN";
} | {
    type: "RECORD_FIELD";
    field: string;
    aspect: string;
    sourceFieldType: string;
    dynamicField?: string;
    dynamicFieldAspect?: string;
    required?: boolean;
} | {
    type: "REFERENCE";
    realType: ValueType;
    value: ReferenceValue;
    label?: string;
    multiple?: boolean;
};
export type LikeMode = "STARTS_WITH" | "ENDS_WITH" | "CONTAINS" | "LEGACY";
export type DateTimeUnit = "SECOND" | "MINUTE" | "HOUR" | "DAY" | "WEEK" | "MONTH" | "QUARTER" | "YEAR";
/** Properties shared by every platform field filter. */
export interface FieldFilterOptions<Field = string, ReferenceValue = FilterReference> {
    field?: Field;
    leftValue?: FilterValue<Field, ReferenceValue>;
    aspect?: Field;
    semantic?: boolean;
}
export interface EqualsFilter<Field = string, ReferenceValue = FilterReference> extends FieldFilterOptions<Field, ReferenceValue> {
    type: "EQUALS";
    value: FilterValue<Field, ReferenceValue>;
    not?: boolean;
}
export interface GreaterThanFilter<Field = string, ReferenceValue = FilterReference> extends FieldFilterOptions<Field, ReferenceValue> {
    type: "GREATER_THAN";
    value: FilterValue<Field, ReferenceValue>;
}
export interface GreaterThanEqualsFilter<Field = string, ReferenceValue = FilterReference> extends FieldFilterOptions<Field, ReferenceValue> {
    type: "GREATER_THAN_EQUALS";
    value: FilterValue<Field, ReferenceValue>;
}
export interface LessThanFilter<Field = string, ReferenceValue = FilterReference> extends FieldFilterOptions<Field, ReferenceValue> {
    type: "LESS_THAN";
    value: FilterValue<Field, ReferenceValue>;
}
export interface LessThanEqualsFilter<Field = string, ReferenceValue = FilterReference> extends FieldFilterOptions<Field, ReferenceValue> {
    type: "LESS_THAN_EQUALS";
    value: FilterValue<Field, ReferenceValue>;
}
export interface LikeFilter<Field = string, ReferenceValue = FilterReference> extends FieldFilterOptions<Field, ReferenceValue> {
    type: "LIKE";
    value: FilterValue<Field, ReferenceValue>;
    not?: boolean;
    caseInsensitive?: boolean;
    mode?: LikeMode;
}
export interface InFilter<Field = string, ReferenceValue = FilterReference> extends FieldFilterOptions<Field, ReferenceValue> {
    type: "IN";
    values: FilterValue<Field, ReferenceValue>[];
    not?: boolean;
}
export interface BetweenFilter<Field = string, ReferenceValue = FilterReference> extends FieldFilterOptions<Field, ReferenceValue> {
    type: "BETWEEN";
    min: FilterValue<Field, ReferenceValue>;
    max: FilterValue<Field, ReferenceValue>;
    not?: boolean;
}
/** Field falls within a relative range described by the provider HCL schema. */
export interface CurrentRangeFilter<Field = string, ReferenceValue = FilterReference> extends FieldFilterOptions<Field, ReferenceValue> {
    type: "CURRENT_RANGE";
    unit: DateTimeUnit;
    isoWeek?: boolean;
}
/** Field falls within consecutive relative ranges described by the provider HCL schema. */
export interface ConsecutiveRangeFilter<Field = string, ReferenceValue = FilterReference> extends FieldFilterOptions<Field, ReferenceValue> {
    type: "CONSECUTIVE_RANGE";
    unit: DateTimeUnit;
    count: number;
    offset: number;
    isoWeek?: boolean;
}
export interface ContainsFilter<Field = string, ReferenceValue = FilterReference> extends FieldFilterOptions<Field, ReferenceValue> {
    type: "CONTAINS";
    values: FilterValue<Field, ReferenceValue>[];
    not?: boolean;
}
export interface OverlapsFilter<Field = string, ReferenceValue = FilterReference> extends FieldFilterOptions<Field, ReferenceValue> {
    type: "OVERLAPS";
    values: FilterValue<Field, ReferenceValue>[];
    not?: boolean;
}
export interface IsNullFilter<Field = string, ReferenceValue = FilterReference> extends FieldFilterOptions<Field, ReferenceValue> {
    type: "IS_NULL";
    not?: boolean;
}
export interface AndFilter<Field = string, ReferenceValue = FilterReference> {
    type: "AND";
    children: readonly Filter<Field, ReferenceValue>[];
}
export interface OrFilter<Field = string, ReferenceValue = FilterReference> {
    type: "OR";
    children: readonly Filter<Field, ReferenceValue>[];
}
export interface TrueFilter {
    type: "TRUE";
}
export interface FalseFilter {
    type: "FALSE";
}
export type Filter<Field = unknown, ReferenceValue = unknown> = EqualsFilter<Field, ReferenceValue> | GreaterThanFilter<Field, ReferenceValue> | GreaterThanEqualsFilter<Field, ReferenceValue> | LessThanFilter<Field, ReferenceValue> | LessThanEqualsFilter<Field, ReferenceValue> | LikeFilter<Field, ReferenceValue> | InFilter<Field, ReferenceValue> | BetweenFilter<Field, ReferenceValue> | CurrentRangeFilter<Field, ReferenceValue> | ConsecutiveRangeFilter<Field, ReferenceValue> | ContainsFilter<Field, ReferenceValue> | OverlapsFilter<Field, ReferenceValue> | IsNullFilter<Field, ReferenceValue> | AndFilter<Field, ReferenceValue> | OrFilter<Field, ReferenceValue> | TrueFilter | FalseFilter;
